{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "MSSQL security alerts are not sent to account administrators",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The enabled MSSQL security alert policy does not set email_account_admins, so subscription administrators may not be notified when database threats are detected."
    },
    {
      "check_id": "AVD-AZU-0018",
      "title": "MSSQL security alert policy has no notification email addresses",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The policy does not configure email_addresses, leaving no explicit security contacts to receive threat alerts."
    }
  ],
  "patched_code": "variable "security_alert_email_addresses" {
  description = "Email addresses that receive MSSQL security threat alerts."
  type        = set(string)

  validation {
    condition     = length(var.security_alert_email_addresses) > 0
    error_message = "At least one security alert email address must be provided."
  }
}

resource "azurerm_mssql_server_security_alert_policy" "recovery_db_alerts" {
  resource_group_name        = azurerm_resource_group.dr_platform.name
  server_name                = azurerm_mssql_server.recovery_sql_server.name
  state                      = "Enabled"
  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint
  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key
  email_account_admins       = true
  email_addresses            = var.security_alert_email_addresses
  disabled_alerts = [
    "Sql_Injection",
    "Data_Exfiltration"
  ]
  retention_days = 20
}
",
  "fix_summary": "Enabled security alert notifications to account administrators and added a required, validated input for explicit threat-alert email recipients without hard-coding contact details."
}
